insert into segments (module_id, segment_code, title, script_text,
  tones, tone_map, condition, script_note, section, sort_order,
  coaching, client_should_feel, verbatim, status) values
  ((select id from modules where script_id = '116a3615-57b5-4a87-aeac-4256d06dc3df' and language = 'es' and title = $vn$Repaso del contrato$vn$), $vn$CONES-011$vn$, $vn$Remaining Benefits And Finish$vn$, $vn$Defensa en Litigios, que te cubre en caso de que alguna vez enfrentes un litigio civil. Esto cubre cualquier tarifa de presentación y negociaciones. Fresh Start: Los pagos que estás haciendo al programa se reportarán como una línea de crédito positiva en tu reporte de crédito. Programa de Descuentos Access: Te permite ahorrar $500 adicionales al mes usando el portal de descuentos de Slate y la aplicación para teléfono inteligente. Naturaleza de los Servicios: Slate no es un bufete de abogados y utiliza terceros para proporcionar los beneficios. Ahora, pasando a la siguiente página, simplemente repasa el arbitraje estándar y las disputas. Por favor haz clic en el último Cuadro Amarillo de Firma. Y después haz clic en el botón morado Finish.$vn$, array[]::text[], $vn$[{"tone": "", "text": "Defensa en Litigios, que te cubre en caso de que alguna vez enfrentes un litigio civil. Esto cubre cualquier tarifa de presentación y negociaciones. Fresh Start: Los pagos que estás haciendo al programa se reportarán como una línea de crédito positiva en tu reporte de crédito. Programa de Descuentos Access: Te permite ahorrar $500 adicionales al mes usando el portal de descuentos de Slate y la aplicación para teléfono inteligente. Naturaleza de los Servicios: Slate no es un bufete de abogados y utiliza terceros para proporcionar los beneficios. Ahora, pasando a la siguiente página, simplemente repasa el arbitraje estándar y las disputas. Por favor haz clic en el último Cuadro Amarillo de Firma. Y después haz clic en el botón morado Finish."}]$vn$::jsonb, null, null, $vn$Beneficios legales$vn$, 110, $vn$Warm through the benefits, then flatten into Plain Talk for the final instructions so they know the section is ending.$vn$, $vn$We are finished with the paperwork.$vn$, false, 'published'),
  ((select id from modules where script_id = '116a3615-57b5-4a87-aeac-4256d06dc3df' and language = 'es' and title = $vn$Preguntas de cumplimiento$vn$), $vn$CMPES-001$vn$, $vn$Set Up The Questions$vn$, $vn$¡Felicidades por completar tus documentos! Ahora, hay algunas preguntas de cumplimiento que te van a hacer y necesitarán recibir una respuesta de SÍ, una vez que conecte a tu administrador de cuenta en la llamada, así que quiero revisar esas preguntas contigo ahora por si tienes alguna pregunta o necesitas más aclaración, ¿OK?$vn$, array[]::text[], $vn$[{"tone": "", "text": "¡Felicidades por completar tus documentos! Ahora, hay algunas preguntas de cumplimiento que te van a hacer y necesitarán recibir una respuesta de SÍ, una vez que conecte a tu administrador de cuenta en la llamada, así que quiero revisar esas preguntas contigo ahora por si tienes alguna pregunta o necesitas más aclaración, ¿OK?"}]$vn$::jsonb, null, $vn$Una vez que recibas el contrato de regreso$vn$, null, 10, $vn$Bright on the congratulations, then straightforward. Framing this as a preview rather than a test keeps them relaxed.$vn$, $vn$Nothing here is going to catch me out.$vn$, false, 'published'),
  ((select id from modules where script_id = '116a3615-57b5-4a87-aeac-4256d06dc3df' and language = 'es' and title = $vn$Preguntas de cumplimiento$vn$), $vn$CMPES-002$vn$, $vn$The Five Questions$vn$, $vn$¿Entiendes que esto no es un préstamo? ¿Entiendes que esto no es un Programa de Liquidación de Deudas? ¿Entiendes que los pagos que haces van directamente a Bolton Services Group? ¿Entiendes que las cuentas inscritas en este programa tendrán que pasar a cobranzas para que podamos comenzar el proceso de disputa? ¿Entiendes que este programa es una colaboración y que tu participación es necesaria?$vn$, array[]::text[], $vn$[{"tone": "", "text": "¿Entiendes que esto no es un préstamo? ¿Entiendes que esto no es un Programa de Liquidación de Deudas? ¿Entiendes que los pagos que haces van directamente a Bolton Services Group? ¿Entiendes que las cuentas inscritas en este programa tendrán que pasar a cobranzas para que podamos comenzar el proceso de disputa? ¿Entiendes que este programa es una colaboración y que tu participación es necesaria?"}]$vn$::jsonb, null, null, null, 20, $vn$One question at a time with a real pause after each. Do not run them together. If any of these is news to them, you want to find out here and not on the recorded verification.$vn$, $vn$I already knew all of these.$vn$, false, 'published'),
  ((select id from modules where script_id = '116a3615-57b5-4a87-aeac-4256d06dc3df' and language = 'es' and title = $vn$El remate$vn$), $vn$FINES-001$vn$, $vn$Congratulations$vn$, $vn$¡Muy bien (Nombre del Cliente)! Quiero ser el primero en decirte Felicidades por dar el paso correcto hacia la libertad financiera… Por fin hay una meta y una luz al final del túnel. Ten en cuenta que sin nosotros, el maratón que estabas corriendo era una carrera de 20 a 30 años; nosotros la hemos reducido a una caminata de 2 años por el parque…$vn$, array[]::text[], $vn$[{"tone": "", "text": "¡Muy bien (Nombre del Cliente)! Quiero ser el primero en decirte Felicidades por dar el paso correcto hacia la libertad financiera… Por fin hay una meta y una luz al final del túnel. Ten en cuenta que sin nosotros, el maratón que estabas corriendo era una carrera de 20 a 30 años; nosotros la hemos reducido a una caminata de 2 años por el parque…"}]$vn$::jsonb, null, null, null, 10, $vn$Genuine warmth, not a victory lap. They just did something that scared them.$vn$, $vn$I did the right thing.$vn$, false, 'published'),
  ((select id from modules where script_id = '116a3615-57b5-4a87-aeac-4256d06dc3df' and language = 'es' and title = $vn$El remate$vn$), $vn$FINES-002$vn$, $vn$Be Patient$vn$, $vn$Pero recuerda… Esto no va a suceder de la noche a la mañana, igual que tu deuda no apareció de la noche a la mañana. Así que POR FAVOR, lo último que quiero dejarte es que por favor tengas paciencia. Una vez que lleves esto hasta el final, NO TENGO NINGUNA DUDA, igual que todos mis otros clientes, tu crédito estará donde quieres que esté y, lo más importante, la deuda HABRÁ DESAPARECIDO y tendrás todas las herramientas que necesitas para nunca volver a pasar por esto. No pierdas de vista la meta (Nombre del Cliente)… Estamos aquí para ti en CADA paso del camino, ¿ok?$vn$, array[]::text[], $vn$[{"tone": "", "text": "Pero recuerda… Esto no va a suceder de la noche a la mañana, igual que tu deuda no apareció de la noche a la mañana. Así que POR FAVOR, lo último que quiero dejarte es que por favor tengas paciencia. Una vez que lleves esto hasta el final, NO TENGO NINGUNA DUDA, igual que todos mis otros clientes, tu crédito estará donde quieres que esté y, lo más importante, la deuda HABRÁ DESAPARECIDO y tendrás todas las herramientas que necesitas para nunca volver a pasar por esto. No pierdas de vista la meta (Nombre del Cliente)… Estamos aquí para ti en CADA paso del camino, ¿ok?"}]$vn$::jsonb, null, null, null, 20, $vn$Slow all the way down. This is the segment that determines whether they are still enrolled in month four, so it matters more than it looks.$vn$, $vn$Progress will be slow and that is normal.$vn$, false, 'published');
